for (const r of [12,13,14]) for (const c of cols) {
  let f = `${c}$8`;
  f = `IF($B${r}=$B$8,${f})`;
  for (let k = 7; k >= 2; k--) f = `IF($B${r}=$B$${k},${c}$${k},${f})`;
  wb.getRange(`${c}${r}`).setValue('=' + f);
}
const chk = {};
for (const r of [12,13,14]) chk[r] = cols.map(c => wb.getRange(`${c}${r}`).getCell().getValue());
